simple.c:
int add(int a, int b) {
    return a + b;
}

complex.c:
long calc(long a, long b, long c, long d,
          long e, long f, long g, long h) {
    return a*b + c*d + e*f + g*h;
}

variadic.c:
int printf(const char* fmt, ...) {
    va_list ap;
    va_start(ap, fmt);
    int result = vfprintf(stdout, fmt, ap);
    va_end(ap);
    return result;
}
